import React, { useEffect, useMemo, useRef, useState } from "react";
import {
  Trophy,
  Plus,
  MoreVertical,
  ChevronLeft,
  TrendingUp,
  SlidersHorizontal,
  X,
  Trash2,
  Search,
  Pencil,
  Delete as Backspace,
} from "lucide-react";

/* ---------------------------------------------------------------- tokens */

const C = {
  ink: "#0E1214",
  surface: "#171D20",
  raised: "#212A2E",
  line: "#2C3639",
  text: "#EEF3F2",
  muted: "#8B979B",
  brass: "#E3A33B",
};

const F = {
  display:
    "'Arial Narrow', 'Helvetica Neue Condensed', 'Roboto Condensed', system-ui, sans-serif",
  ui: "system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif",
  num: "ui-monospace, 'SF Mono', Menlo, Consolas, monospace",
};

/* Your log lives in this phone's browser storage. On the very first open it is
   filled from seed.json (your imported history); after that seed.json is ignored.
   Export a backup now and then: browser storage belongs to this one device. */
const STORAGE_KEY = "po-log-v1";
const BACKUP_KEY = "po-last-backup";

function readLocal() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch (e) {
    return null;
  }
}

function writeLocal(d) {
  try {
    localStorage.setItem(
      STORAGE_KEY,
      JSON.stringify({ version: 1, savedAt: Date.now(), exercises: d.exercises, sets: d.sets })
    );
    return true;
  } catch (e) {
    return false;
  }
}

function isLog(x) {
  return x && Array.isArray(x.exercises) && Array.isArray(x.sets);
}
const RIR_SCALE = [0, 1, 2, 3, 4];
const MUSCLES = ["Bicep", "Tricep", "Shoulders", "Chest", "Back", "Legs"];
const SIDES = [
  { id: "L", name: "Left" },
  { id: "R", name: "Right" },
];
const sideName = (id) => SIDES.find((s) => s.id === id)?.name || null;

const MUSCLE_COLORS = {
  Bicep: "#EF6461",
  Tricep: "#F5954A",
  Shoulders: "#4AA8F0",
  Chest: "#EC74B5",
  Back: "#33C3A9",
  Legs: "#A78BFA",
};
/* One shared color for the highlighted muscle on tricep, chest and shoulders. */
const EMBLEM_HIGHLIGHT = "#F4F7F6";


/* Muscle emblems: white masks cut from the generated art, tinted in code.
   body = the figure, hi = the highlighted muscle (tricep, chest, shoulders). */
const EMBLEMS = {
  Legs: {
    body: "data:image/png;base64,",
    hi: null,
  },
  Back: {
    body: "data:image/png;base64,",
    hi: null,
  },
  Shoulders: {
    body: "data:image/png;base64,",
    hi: "data:image/png;base64,",
  },
  Chest: {
    body: "data:image/png;base64,",
    hi: "data:image/png;base64,",
  },
  Tricep: {
    body: "data:image/png;base64,",
    hi: "data:image/png;base64,",
  },
  Bicep: {
    body: "data:image/png;base64,",
    hi: null,
  },
};



/* ----------------------------------------------------------- data helpers */

const uid = () =>
  Math.random().toString(36).slice(2, 9) + Date.now().toString(36).slice(-4);

const num = (x) => String(Math.round(x * 100) / 100);

const epley = (weight, reps) => weight * (1 + reps / 30);

const fmtDay = (iso) => {
  const d = new Date(iso);
  const now = new Date();
  const opts =
    d.getFullYear() === now.getFullYear()
      ? { weekday: "short", month: "short", day: "numeric" }
      : { month: "short", day: "numeric", year: "numeric" };
  return d.toLocaleDateString(undefined, opts);
};

const fmtShort = (iso) => {
  const d = new Date(iso);
  return `${d.getMonth() + 1}/${d.getDate()}`;
};

const dayKey = (iso) => new Date(iso).toDateString();

const rirLabel = (rir, maybe) =>
  maybe ? `${num(rir)} maybe ${num(rir + 1)} RIR` : `${num(rir)} RIR`;

const fmtAgo = (iso) => {
  const t = new Date(iso);
  const n = new Date();
  const a = new Date(t.getFullYear(), t.getMonth(), t.getDate());
  const b = new Date(n.getFullYear(), n.getMonth(), n.getDate());
  const days = Math.round((b - a) / 86400000);
  if (days <= 0) return "Today";
  if (days === 1) return "Yesterday";
  if (days < 7) return `${days} days ago`;
  if (days < 14) return "1 week ago";
  if (days < 60) return `${Math.floor(days / 7)} weeks ago`;
  if (days < 365) return `${Math.max(2, Math.floor(days / 30))} months ago`;
  const years = Math.floor(days / 365);
  return years === 1 ? "1 year ago" : `${years} years ago`;
};

const byTime = (a, b) => new Date(a.at) - new Date(b.at);

/* Records: for each distinct weight, most reps wins. Ties keep the earlier set.
   Unilateral sets compete only against the same side. */
function recordIds(sets) {
  const best = new Map();
  [...sets].sort(byTime).forEach((s) => {
    const k = `${s.side || "-"}|${s.weight}`;
    const cur = best.get(k);
    if (!cur || s.reps > cur.reps) best.set(k, s);
  });
  return new Set([...best.values()].map((s) => s.id));
}

/* --------------------------------------------------------------- storage */

/* Older saves stored effort as RPE. Carry them over as reps in reserve. */
function migrate(d) {
  return {
    exercises: d.exercises.map((e) => ({
      ...e,
      muscle: e.muscle !== undefined ? e.muscle : null,
      variants: e.variants || [],
      unilateral: Boolean(e.unilateral),
      note: e.note || "",
    })),
    sets: (d.sets || []).map((s) => {
      if (s.rir !== undefined) return s;
      const { rpe, ...rest } = s;
      return {
        ...rest,
        rir: rpe === null || rpe === undefined ? null : Math.round((10 - rpe) * 10) / 10,
      };
    }),
  };
}

/* ------------------------------------------------------------ primitives */

function Eyebrow({ children, className = "" }) {
  return (
    <div
      className={`text-[10px] uppercase tracking-[0.18em] ${className}`}
      style={{ color: C.muted, fontFamily: F.ui, fontWeight: 600 }}
    >
      {children}
    </div>
  );
}

function Chip({ active, onClick, children, title }) {
  return (
    <button
      type="button"
      onClick={onClick}
      title={title}
      className="px-3 h-10 rounded-lg text-sm transition-colors"
      style={{
        fontFamily: F.ui,
        fontWeight: 600,
        background: active ? C.text : "transparent",
        color: active ? C.ink : C.text,
        border: `1px solid ${active ? C.text : C.line}`,
      }}
    >
      {children}
    </button>
  );
}

function Emblem({ muscle, size = 38 }) {
  const art = muscle ? EMBLEMS[muscle] : null;
  if (!art) {
    return (
      <span
        aria-hidden="true"
        className="shrink-0 rounded-[10px]"
        style={{ width: size, height: size, border: `1px dashed ${C.line}` }}
      />
    );
  }
  const color = MUSCLE_COLORS[muscle];
  const layer = (url, fill) => ({
    position: "absolute",
    inset: Math.round(size * 0.1),
    backgroundColor: fill,
    WebkitMaskImage: `url(${url})`,
    maskImage: `url(${url})`,
    WebkitMaskSize: "contain",
    maskSize: "contain",
    WebkitMaskRepeat: "no-repeat",
    maskRepeat: "no-repeat",
    WebkitMaskPosition: "center",
    maskPosition: "center",
  });
  return (
    <span
      role="img"
      aria-label={muscle}
      title={muscle}
      className="shrink-0 relative rounded-[10px]"
      style={{ width: size, height: size, background: `${color}29` }}
    >
      <span style={layer(art.body, color)} />
      {art.hi ? <span style={layer(art.hi, EMBLEM_HIGHLIGHT)} /> : null}
    </span>
  );
}

function GhostButton({ onClick, children, active, ariaLabel }) {
  return (
    <button
      type="button"
      onClick={onClick}
      aria-label={ariaLabel}
      className="h-11 px-3 rounded-lg flex items-center gap-2 text-sm"
      style={{
        fontFamily: F.ui,
        fontWeight: 600,
        background: active ? C.text : C.surface,
        color: active ? C.ink : C.text,
        border: `1px solid ${active ? C.text : C.line}`,
      }}
    >
      {children}
    </button>
  );
}

/* ------------------------------------------------------------------- app */

export default function App() {
  const [data, setData] = useState({ exercises: [], sets: [] });
  const [status, setStatus] = useState("loading"); // loading | ready
  const [writable, setWritable] = useState(true);
  const [saveError, setSaveError] = useState("");
  const [openId, setOpenId] = useState(null);

  useEffect(() => {
    let alive = true;
    (async () => {
      let start = readLocal();
      if (!isLog(start)) {
        try {
          const r = await fetch("seed.json", { cache: "no-store" });
          start = r.ok ? await r.json() : null;
        } catch (e) {
          start = null;
        }
        if (!isLog(start)) start = { exercises: [], sets: [] };
        writeLocal(start);
      }
      if (!alive) return;
      setData(migrate(start));
      setStatus("ready");
      try {
        if (navigator.storage && navigator.storage.persist) navigator.storage.persist();
      } catch (e) {
        /* ignore */
      }
    })();
    return () => {
      alive = false;
    };
  }, []);

  useEffect(() => {
    if (status !== "ready") return;
    const ok = writeLocal(data);
    setWritable(ok);
    setSaveError(ok ? "" : "Couldn't save to this phone's storage. Export a backup now.");
  }, [data, status]);

  const exportBackup = async () => {
    const day = new Date().toISOString().slice(0, 10);
    const name = `progressive-overload-backup-${day}.json`;
    const body = JSON.stringify(
      { version: 1, savedAt: Date.now(), exercises: data.exercises, sets: data.sets },
      null,
      1
    );
    const file = new File([body], name, { type: "application/json" });
    try {
      if (navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share({ files: [file], title: "Progressive Overload backup" });
      } else {
        const url = URL.createObjectURL(file);
        const a = document.createElement("a");
        a.href = url;
        a.download = name;
        document.body.appendChild(a);
        a.click();
        a.remove();
        setTimeout(() => URL.revokeObjectURL(url), 2000);
      }
      try {
        localStorage.setItem(BACKUP_KEY, String(Date.now()));
      } catch (e) {
        /* ignore */
      }
      return true;
    } catch (e) {
      return false; // share sheet dismissed
    }
  };

  const importBackup = async (file) => {
    try {
      const parsed = JSON.parse(await file.text());
      if (!isLog(parsed)) return "That file isn't a Progressive Overload backup.";
      setData(migrate(parsed));
      setOpenId(null);
      return "";
    } catch (e) {
      return "That file couldn't be read. Pick a .json backup exported from this app.";
    }
  };

  const exercises = useMemo(
    () =>
      [...data.exercises].sort((a, b) =>
        a.name.localeCompare(b.name, undefined, { sensitivity: "base" })
      ),
    [data.exercises]
  );

  const open = data.exercises.find((e) => e.id === openId) || null;

  /* mutations */
  /* Create or update an exercise from the exercise page. Variants removed there
     are cleared from any sets that used them. */
  const saveExercise = (ex, removedVariantIds = []) => {
    const gone = new Set(removedVariantIds);
    setData((d) => ({
      exercises: d.exercises.some((e) => e.id === ex.id)
        ? d.exercises.map((e) => (e.id === ex.id ? ex : e))
        : [...d.exercises, ex],
      sets: gone.size
        ? d.sets.map((s) => (gone.has(s.variantId) ? { ...s, variantId: null } : s))
        : d.sets,
    }));
  };

  const addVariant = (exId, name) => {
    const variant = { id: uid(), name: name.trim() };
    setData((d) => ({
      ...d,
      exercises: d.exercises.map((e) =>
        e.id === exId ? { ...e, variants: [...e.variants, variant] } : e
      ),
    }));
    return variant.id;
  };

  const addSet = (set) => setData((d) => ({ ...d, sets: [...d.sets, set] }));

  const updateSet = (set) =>
    setData((d) => ({
      ...d,
      sets: d.sets.map((s) => (s.id === set.id ? set : s)),
    }));

  const deleteSet = (id) =>
    setData((d) => ({ ...d, sets: d.sets.filter((s) => s.id !== id) }));

  if (status === "loading") {
    return (
      <div
        className="min-h-screen flex items-center justify-center"
        style={{ background: C.ink, color: C.muted, fontFamily: F.ui }}
      >
        <Eyebrow>Loading your log</Eyebrow>
      </div>
    );
  }

  return (
    <div
      className="min-h-screen w-full"
      style={{ background: C.ink, paddingTop: "env(safe-area-inset-top, 0px)" }}
    >
      <style>{`
        * { -webkit-tap-highlight-color: transparent; }
        button:focus-visible, input:focus-visible, textarea:focus-visible {
          outline: 2px solid ${C.text}; outline-offset: 2px;
        }
        input::placeholder, textarea::placeholder { color: ${C.muted}; }
        .no-bar::-webkit-scrollbar { height: 6px; }
        .no-bar::-webkit-scrollbar-thumb { background: ${C.line}; border-radius: 3px; }
        @media (prefers-reduced-motion: reduce) {
          * { transition: none !important; animation: none !important; }
        }
      `}</style>

      <div className="mx-auto w-full max-w-md">
        {saveError ? (
          <div
            role="alert"
            className="mx-4 mt-3 rounded-xl px-3 py-2.5 text-sm"
            style={{ background: C.raised, color: C.brass, fontFamily: F.ui }}
          >
            {saveError}
          </div>
        ) : null}
        {open ? (
          <ExerciseScreen
            key={open.id}
            exercise={open}
            allSets={data.sets.filter((s) => s.exerciseId === open.id)}
            onBack={() => setOpenId(null)}
            onLog={addSet}
            onUpdate={updateSet}
            onDeleteSet={deleteSet}
            onAddVariant={addVariant}
            onSaveExercise={saveExercise}
            exerciseNames={data.exercises.map((e) => ({ id: e.id, name: e.name }))}
          />
        ) : (
          <HomeScreen
            exercises={exercises}
            sets={data.sets}
            persists={writable}
            onExport={exportBackup}
            onImport={importBackup}
            onOpen={setOpenId}
            onSaveExercise={(ex, removed) => {
              const isNew = !data.exercises.some((e) => e.id === ex.id);
              saveExercise(ex, removed);
              if (isNew) setOpenId(ex.id);
            }}
          />
        )}
      </div>
    </div>
  );
}

function UnilateralToggle({ on, onChange }) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={on}
      onClick={() => onChange(!on)}
      className="w-full min-h-14 rounded-xl px-4 py-3 flex items-center justify-between text-left"
      style={{
        background: C.raised,
        border: `1px solid ${on ? C.text : C.line}`,
        color: C.text,
        fontFamily: F.ui,
      }}
    >
      <span>
        <span className="block" style={{ fontWeight: 600 }}>
          Unilateral
        </span>
        <span className="block text-[12px]" style={{ color: C.muted }}>
          One arm or leg at a time. Each set asks for left or right.
        </span>
      </span>
      <span
        className="shrink-0 ml-3 rounded-full relative"
        style={{
          width: 44,
          height: 26,
          background: on ? C.text : C.line,
          transition: "background 120ms",
        }}
      >
        <span
          className="absolute rounded-full"
          style={{
            top: 3,
            left: on ? 21 : 3,
            width: 20,
            height: 20,
            background: on ? C.ink : C.muted,
            transition: "left 120ms",
          }}
        />
      </span>
    </button>
  );
}

/* ------------------------------------------------------------------ home */

function HomeScreen({ exercises, sets, persists, onOpen, onSaveExercise, onExport, onImport }) {
  const [query, setQuery] = useState("");
  const [muscleFilter, setMuscleFilter] = useState(null);
  const [form, setForm] = useState(null); // null | { id } for edit | { id: null } for new

  const lastSetAt = useMemo(() => {
    const m = new Map();
    sets.forEach((s) => {
      const cur = m.get(s.exerciseId);
      if (!cur || new Date(s.at) > new Date(cur)) m.set(s.exerciseId, s.at);
    });
    return m;
  }, [sets]);

  const q = query.trim().toLowerCase();
  const shown = exercises.filter(
    (e) =>
      (muscleFilter === null || e.muscle === muscleFilter) &&
      (!q || e.name.toLowerCase().includes(q))
  );

  if (form) {
    const editing = form.id ? exercises.find((e) => e.id === form.id) : null;
    return (
      <ExerciseForm
        exercise={editing}
        initialName={editing ? "" : query.trim()}
        initialMuscle={editing ? null : muscleFilter}
        exerciseNames={exercises.map((e) => ({ id: e.id, name: e.name }))}
        onClose={() => setForm(null)}
        onSave={(ex, removed) => {
          onSaveExercise(ex, removed);
          setForm(null);
          if (!editing) setQuery("");
        }}
      />
    );
  }

  return (
    <div className="px-4 pt-8 pb-16">
      <Eyebrow>Training log</Eyebrow>
      <h1
        className="mt-1 uppercase leading-[0.9]"
        style={{
          fontFamily: F.display,
          fontSize: 44,
          fontWeight: 700,
          letterSpacing: "0.01em",
          color: C.text,
        }}
      >
        Progressive
        <br />
        Overload
      </h1>

      <div className="mt-6 flex items-start gap-3">
        <div className="relative flex-1 min-w-0">
          <Search
            size={18}
            className="absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none"
            style={{ color: C.muted }}
          />
          <input
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search exercises"
            aria-label="Search exercises"
            className="w-full h-12 pl-10 pr-10 rounded-xl text-base"
            style={{
              background: C.surface,
              border: `1px solid ${C.line}`,
              color: C.text,
              fontFamily: F.ui,
            }}
          />
          {query ? (
            <button
              type="button"
              onClick={() => setQuery("")}
              aria-label="Clear search"
              className="absolute right-1 top-1/2 -translate-y-1/2 h-10 w-10 flex items-center justify-center"
              style={{ color: C.muted }}
            >
              <X size={18} />
            </button>
          ) : null}
        </div>
        <button
          type="button"
          onClick={() => setForm({ id: null })}
          className="shrink-0 flex flex-col items-center"
          style={{ width: 64 }}
        >
          <span
            className="h-12 w-12 rounded-xl flex items-center justify-center"
            style={{ background: C.text, color: C.ink }}
          >
            <Plus size={22} strokeWidth={2.5} />
          </span>
          <span
            className="mt-1 text-[11px] leading-tight text-center"
            style={{ color: C.muted, fontFamily: F.ui, fontWeight: 600 }}
          >
            Add new exercise
          </span>
        </button>
      </div>

      {!persists ? (
        <div className="mt-2 text-sm" style={{ color: C.muted, fontFamily: F.ui }}>
          Changes can't be saved on this device right now. Export a backup.
        </div>
      ) : null}

      <div className="mt-5 flex flex-wrap gap-2">
        <Chip active={muscleFilter === null} onClick={() => setMuscleFilter(null)}>
          All
        </Chip>
        {MUSCLES.map((m) => (
          <Chip
            key={m}
            active={muscleFilter === m}
            onClick={() => setMuscleFilter(muscleFilter === m ? null : m)}
          >
            {m}
          </Chip>
        ))}
      </div>

      <div className="mt-6">
        <Eyebrow>
          {shown.length} {shown.length === 1 ? "exercise" : "exercises"}
          {muscleFilter ? ` · ${muscleFilter.toLowerCase()}` : ""}
          {q ? ` · "${query.trim()}"` : ""}
        </Eyebrow>

        {shown.length === 0 ? (
          <div
            className="mt-3 rounded-xl p-5 text-sm"
            style={{
              background: C.surface,
              border: `1px dashed ${C.line}`,
              color: C.muted,
              fontFamily: F.ui,
            }}
          >
            {exercises.length === 0 ? (
              "Nothing here yet. Tap the plus to add your first exercise."
            ) : q ? (
              <>
                <div>No exercise matches "{query.trim()}".</div>
                <button
                  type="button"
                  onClick={() => setForm({ id: null })}
                  className="mt-3 h-11 px-4 rounded-lg flex items-center gap-2"
                  style={{ background: C.text, color: C.ink, fontWeight: 700 }}
                >
                  <Plus size={18} strokeWidth={2.5} />
                  Create "{query.trim()}"
                </button>
              </>
            ) : (
              `Nothing tagged ${muscleFilter.toLowerCase()} yet. Set a muscle group from an exercise's three dot menu.`
            )}
          </div>
        ) : (
          <ul className="mt-3 space-y-2">
            {shown.map((ex) => {
              const at = lastSetAt.get(ex.id);
              const meta = [
                ex.unilateral ? "Unilateral" : null,
                ex.variants.length
                  ? `${ex.variants.length} ${ex.variants.length === 1 ? "variant" : "variants"}`
                  : null,
              ]
                .filter(Boolean)
                .join(" · ");
              return (
                <li key={ex.id}>
                  <div
                    className="flex items-stretch rounded-xl overflow-hidden"
                    style={{ background: C.surface, border: `1px solid ${C.line}` }}
                  >
                    <button
                      type="button"
                      onClick={() => onOpen(ex.id)}
                      className="flex-1 min-w-0 text-left pl-3 pr-4 py-3 flex items-center gap-3"
                    >
                      <Emblem muscle={ex.muscle} />
                      <span className="min-w-0 flex-1">
                        <span
                          className="block text-[17px] leading-tight"
                          style={{ color: C.text, fontFamily: F.ui, fontWeight: 650 }}
                        >
                          {ex.name}
                        </span>
                        {ex.note ? (
                          <span
                            className="block mt-1 text-[13px] leading-snug line-clamp-2"
                            style={{ color: C.text, opacity: 0.72, fontFamily: F.ui }}
                          >
                            {ex.note}
                          </span>
                        ) : null}
                        {meta ? (
                          <span
                            className="block mt-1 text-[12px]"
                            style={{ color: C.muted, fontFamily: F.ui }}
                          >
                            {meta}
                          </span>
                        ) : null}
                      </span>
                      <span
                        className="shrink-0 text-[13px] text-right"
                        style={{ color: at ? C.muted : C.line, fontFamily: F.ui }}
                      >
                        {at ? fmtAgo(at) : "No sets"}
                      </span>
                    </button>
                    <button
                      type="button"
                      aria-label={`Edit ${ex.name}`}
                      onClick={() => setForm({ id: ex.id })}
                      className="w-12 flex items-center justify-center"
                      style={{ color: C.muted, borderLeft: `1px solid ${C.line}` }}
                    >
                      <MoreVertical size={20} />
                    </button>
                  </div>
                </li>
              );
            })}
          </ul>
        )}
      </div>
      <BackupPanel setCount={sets.length} onExport={onExport} onImport={onImport} />
    </div>
  );
}

function BackupPanel({ setCount, onExport, onImport }) {
  const [msg, setMsg] = useState("");
  const [pending, setPending] = useState(null);
  const inputRef = useRef(null);
  let last = null;
  try {
    last = Number(localStorage.getItem(BACKUP_KEY)) || null;
  } catch (e) {
    last = null;
  }
  const btn = {
    border: `1px solid ${C.line}`,
    color: C.text,
    fontFamily: F.ui,
    fontWeight: 600,
  };
  return (
    <section className="mt-10 rounded-xl p-4" style={{ background: C.surface, border: `1px solid ${C.line}` }}>
      <Eyebrow>Backup</Eyebrow>
      <p className="mt-2 text-[13px] leading-snug" style={{ color: C.muted, fontFamily: F.ui }}>
        Your {setCount} sets are stored on this phone. Export a copy every few weeks and keep it in Files or iCloud.
        {last ? ` Last export ${fmtAgo(new Date(last).toISOString()).toLowerCase()}.` : " No export yet."}
      </p>
      <div className="mt-3 grid grid-cols-2 gap-2">
        <button
          type="button"
          onClick={async () => setMsg((await onExport()) ? "Backup exported." : "")}
          className="h-11 rounded-lg text-sm"
          style={{ ...btn, background: C.text, color: C.ink, border: "none" }}
        >
          Export backup
        </button>
        <button type="button" onClick={() => inputRef.current && inputRef.current.click()} className="h-11 rounded-lg text-sm" style={btn}>
          Import backup
        </button>
      </div>
      <input
        ref={inputRef}
        id="po-import"
        type="file"
        accept="application/json,.json"
        className="hidden"
        onChange={(e) => {
          const f = e.target.files && e.target.files[0];
          e.target.value = "";
          if (f) setPending(f);
        }}
      />
      {pending ? (
        <div className="mt-3 flex items-center gap-2">
          <span className="text-sm flex-1" style={{ color: C.muted, fontFamily: F.ui }}>
            Replace everything on this phone with {pending.name}?
          </span>
          <button type="button" onClick={() => setPending(null)} className="h-10 px-3 rounded-lg text-sm" style={btn}>
            Keep
          </button>
          <button
            type="button"
            onClick={async () => {
              const err = await onImport(pending);
              setPending(null);
              setMsg(err || "Backup imported.");
            }}
            className="h-10 px-3 rounded-lg text-sm"
            style={{ background: C.brass, color: C.ink, fontFamily: F.ui, fontWeight: 700 }}
          >
            Replace
          </button>
        </div>
      ) : null}
      {msg ? (
        <div className="mt-2 text-sm" style={{ color: C.text, fontFamily: F.ui }}>
          {msg}
        </div>
      ) : null}
    </section>
  );
}

/* ----------------------------------------------------------------- sheet */

/* Full page rather than an overlay: a nested scroll area traps touch
   scrolling on mobile, so sheets take over the screen and scroll normally. */
function Sheet({ children, onClose, title, subtitle }) {
  useEffect(() => {
    try {
      window.scrollTo(0, 0);
    } catch (e) {
      /* ignore */
    }
  }, []);

  return (
    <div className="px-4 pt-5 pb-16" style={{ background: C.ink }}>
      <div className="flex items-start justify-between gap-3">
        <div className="min-w-0">
          {subtitle ? <Eyebrow>{subtitle}</Eyebrow> : null}
          <div
            className="text-2xl leading-tight"
            style={{ color: C.text, fontFamily: F.ui, fontWeight: 700 }}
          >
            {title}
          </div>
        </div>
        <button
          type="button"
          onClick={onClose}
          aria-label="Close"
          className="h-11 w-11 -mr-2 shrink-0 flex items-center justify-center rounded-lg"
          style={{ color: C.muted }}
        >
          <X size={24} />
        </button>
      </div>
      <div className="mt-5">{children}</div>
    </div>
  );
}


/* -------------------------------------------------------- exercise form */

/* One page for creating and editing an exercise. Nothing is saved until Save. */
function ExerciseForm({ exercise, initialName, initialMuscle, exerciseNames, onClose, onSave }) {
  const isNew = !exercise;
  const [name, setName] = useState(exercise ? exercise.name : initialName || "");
  const [note, setNote] = useState(exercise ? exercise.note || "" : "");
  const [unilateral, setUnilateral] = useState(Boolean(exercise && exercise.unilateral));
  const [muscle, setMuscle] = useState(exercise ? exercise.muscle || null : initialMuscle || null);
  const [variants, setVariants] = useState(
    exercise ? exercise.variants.map((v) => ({ ...v })) : []
  );
  const [draft, setDraft] = useState("");
  const [error, setError] = useState("");

  const field = {
    background: C.surface,
    border: `1px solid ${C.line}`,
    color: C.text,
    fontFamily: F.ui,
  };

  const addDraft = () => {
    const n = draft.trim();
    if (!n) return;
    if (variants.some((v) => v.name.trim().toLowerCase() === n.toLowerCase())) {
      setDraft("");
      return;
    }
    setVariants((vs) => [...vs, { id: uid(), name: n }]);
    setDraft("");
  };

  const save = () => {
    const n = name.trim();
    if (!n) {
      setError("Give the exercise a name.");
      return;
    }
    const clash = exerciseNames.find(
      (e) => e.name.toLowerCase() === n.toLowerCase() && (!exercise || e.id !== exercise.id)
    );
    if (clash) {
      setError(`${n} is already on the list.`);
      return;
    }
    const pending = draft.trim()
      ? [...variants, { id: uid(), name: draft.trim() }]
      : variants;
    const kept = pending
      .map((v) => ({ ...v, name: v.name.trim() }))
      .filter((v) => v.name);
    const keptIds = new Set(kept.map((v) => v.id));
    const removed = exercise
      ? exercise.variants.filter((v) => !keptIds.has(v.id)).map((v) => v.id)
      : [];
    onSave(
      {
        ...(exercise || {}),
        id: exercise ? exercise.id : uid(),
        name: n,
        note: note.trim(),
        unilateral,
        muscle,
        variants: kept,
      },
      removed
    );
  };

  return (
    <Sheet
      onClose={onClose}
      title={isNew ? "New exercise" : "Edit exercise"}
      subtitle={isNew ? "Add to your log" : exercise.name}
    >
      <Eyebrow>Name</Eyebrow>
      <input
        value={name}
        autoFocus={isNew && !name}
        onChange={(e) => {
          setName(e.target.value);
          setError("");
        }}
        placeholder="Lat Pulldown"
        className="mt-2 w-full h-12 px-3 rounded-xl text-base"
        style={field}
      />
      {error ? (
        <div className="mt-2 text-sm" style={{ color: C.brass, fontFamily: F.ui }}>
          {error}
        </div>
      ) : null}

      <div className="mt-5">
        <Eyebrow>Note, optional</Eyebrow>
        <textarea
          value={note}
          onChange={(e) => setNote(e.target.value)}
          rows={3}
          placeholder="Machine upstairs, seat on 4, pad just above the ankle"
          className="mt-2 w-full px-3 py-3 rounded-xl text-base leading-snug resize-none"
          style={field}
        />
        <div className="mt-1 text-[12px]" style={{ color: C.muted, fontFamily: F.ui }}>
          Shows under the name on the list and when you log a set.
        </div>
      </div>

      <div className="mt-5">
        <UnilateralToggle on={unilateral} onChange={setUnilateral} />
      </div>

      <div className="mt-5">
        <Eyebrow>Muscle group</Eyebrow>
        <div className="mt-2 flex flex-wrap gap-2">
          <Chip active={!muscle} onClick={() => setMuscle(null)}>
            None
          </Chip>
          {MUSCLES.map((m) => (
            <Chip key={m} active={muscle === m} onClick={() => setMuscle(muscle === m ? null : m)}>
              {m}
            </Chip>
          ))}
        </div>
      </div>

      <div className="mt-5">
        <Eyebrow>Variants, optional</Eyebrow>
        <div className="mt-2 space-y-2">
          {variants.map((v) => (
            <div key={v.id} className="flex gap-2">
              <input
                value={v.name}
                onChange={(e) =>
                  setVariants((vs) =>
                    vs.map((x) => (x.id === v.id ? { ...x, name: e.target.value } : x))
                  )
                }
                aria-label="Variant name"
                className="flex-1 min-w-0 h-12 px-3 rounded-xl text-base"
                style={field}
              />
              <button
                type="button"
                aria-label={`Remove ${v.name}`}
                onClick={() => setVariants((vs) => vs.filter((x) => x.id !== v.id))}
                className="h-12 w-12 shrink-0 rounded-xl flex items-center justify-center"
                style={{ background: C.surface, border: `1px solid ${C.line}`, color: C.muted }}
              >
                <Trash2 size={18} />
              </button>
            </div>
          ))}
          <div className="flex gap-2">
            <input
              value={draft}
              onChange={(e) => setDraft(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && addDraft()}
              placeholder="Wide grip"
              aria-label="New variant"
              className="flex-1 min-w-0 h-12 px-3 rounded-xl text-base"
              style={{ ...field, borderStyle: "dashed" }}
            />
            <button
              type="button"
              aria-label="Add variant"
              onClick={addDraft}
              className="h-12 w-12 shrink-0 rounded-xl flex items-center justify-center"
              style={{ background: C.text, color: C.ink }}
            >
              <Plus size={20} strokeWidth={2.5} />
            </button>
          </div>
        </div>
        {!isNew && exercise.variants.some((v) => !variants.some((x) => x.id === v.id)) ? (
          <div className="mt-2 text-[12px]" style={{ color: C.muted, fontFamily: F.ui }}>
            Removed variants come off their sets when you save. Weight and reps stay.
          </div>
        ) : null}
      </div>

      <button
        type="button"
        onClick={save}
        className="mt-6 w-full h-14 rounded-xl text-base"
        style={{ background: C.text, color: C.ink, fontFamily: F.ui, fontWeight: 700 }}
      >
        {isNew ? "Create exercise" : "Save changes"}
      </button>
      <button
        type="button"
        onClick={onClose}
        className="mt-2 w-full h-12 rounded-xl flex items-center justify-center gap-1 text-base"
        style={{
          border: `1px solid ${C.line}`,
          color: C.text,
          fontFamily: F.ui,
          fontWeight: 600,
        }}
      >
        <ChevronLeft size={18} />
        Back without saving
      </button>
    </Sheet>
  );
}

/* -------------------------------------------------------- exercise detail */

function ExerciseScreen({
  exercise,
  allSets,
  onBack,
  onLog,
  onUpdate,
  onDeleteSet,
  onAddVariant,
  onSaveExercise,
  exerciseNames,
}) {
  const [weightFilter, setWeightFilter] = useState(null);
  const [variantFilter, setVariantFilter] = useState(null);
  const [sideFilter, setSideFilter] = useState(null);
  const [showFilters, setShowFilters] = useState(false);
  const [showGraph, setShowGraph] = useState(false);
  const [logging, setLogging] = useState(false);
  const [editing, setEditing] = useState(null);
  const [managing, setManaging] = useState(false);

  const sorted = useMemo(() => [...allSets].sort(byTime), [allSets]);
  const records = useMemo(() => recordIds(allSets), [allSets]);

  const weights = useMemo(
    () => [...new Set(allSets.map((s) => s.weight))].sort((a, b) => b - a),
    [allSets]
  );

  const filtered = useMemo(
    () =>
      sorted.filter(
        (s) =>
          (weightFilter === null || s.weight === weightFilter) &&
          (variantFilter === null || s.variantId === variantFilter) &&
          (sideFilter === null || s.side === sideFilter)
      ),
    [sorted, weightFilter, variantFilter, sideFilter]
  );

  const variantName = (id) => exercise.variants.find((v) => v.id === id)?.name || null;
  const activeCount =
    (weightFilter !== null ? 1 : 0) +
    (variantFilter !== null ? 1 : 0) +
    (sideFilter !== null ? 1 : 0);
  const last = sorted[sorted.length - 1];

  const groups = useMemo(() => {
    const out = [];
    [...filtered].reverse().forEach((s) => {
      const k = dayKey(s.at);
      const tail = out[out.length - 1];
      if (tail && tail.key === k) tail.items.push(s);
      else out.push({ key: k, at: s.at, items: [s] });
    });
    return out;
  }, [filtered]);

  if (logging || editing) {
    return (
      <SetSheet
        exercise={exercise}
        lastSet={last}
        editSet={editing}
        presetVariant={variantFilter}
        presetWeight={weightFilter}
        presetSide={sideFilter}
        onAddVariant={(name) => onAddVariant(exercise.id, name)}
        onClose={() => {
          setLogging(false);
          setEditing(null);
        }}
        onSave={(s) => {
          if (editing) onUpdate(s);
          else onLog(s);
          setLogging(false);
          setEditing(null);
        }}
        onDelete={(id) => {
          onDeleteSet(id);
          setEditing(null);
        }}
      />
    );
  }

  if (managing) {
    return (
      <ExerciseForm
        exercise={exercise}
        exerciseNames={exerciseNames}
        onClose={() => setManaging(false)}
        onSave={(ex, removed) => {
          onSaveExercise(ex, removed);
          if (removed.includes(variantFilter)) setVariantFilter(null);
          if (!ex.unilateral) setSideFilter(null);
          setManaging(false);
        }}
      />
    );
  }

  return (
    <div className="px-4 pt-5 pb-28">
      <button
        type="button"
        onClick={onBack}
        className="h-11 -ml-2 px-2 flex items-center gap-1 text-sm"
        style={{ color: C.muted, fontFamily: F.ui, fontWeight: 600 }}
      >
        <ChevronLeft size={20} /> All exercises
      </button>

      <h1
        className="mt-1 uppercase leading-[0.92]"
        style={{
          fontFamily: F.display,
          fontSize: 38,
          fontWeight: 700,
          color: C.text,
          letterSpacing: "0.01em",
        }}
      >
        {exercise.name}
      </h1>

      {exercise.note ? (
        <p
          className="mt-2 text-[14px] leading-snug whitespace-pre-line"
          style={{ color: C.text, opacity: 0.78, fontFamily: F.ui }}
        >
          {exercise.note}
        </p>
      ) : null}

      <div className="mt-3 flex flex-wrap gap-2">
        <GhostButton
          onClick={() => setShowFilters((v) => !v)}
          active={showFilters || activeCount > 0}
          ariaLabel="Filters"
        >
          <SlidersHorizontal size={17} />
          Filter
          {activeCount ? (
            <span style={{ fontFamily: F.num }}>{activeCount}</span>
          ) : null}
        </GhostButton>
        <GhostButton
          onClick={() => setShowGraph((v) => !v)}
          active={showGraph}
          ariaLabel="Graph"
        >
          <TrendingUp size={17} />
          Graph
        </GhostButton>
        <GhostButton onClick={() => setManaging(true)} ariaLabel="Edit exercise">
          <Pencil size={16} />
          Edit
        </GhostButton>
      </div>

      {showFilters ? (
        <div
          className="mt-3 rounded-xl p-3"
          style={{ background: C.surface, border: `1px solid ${C.line}` }}
        >
          <Eyebrow>Weight</Eyebrow>
          <div className="mt-2 flex flex-wrap gap-2">
            <Chip active={weightFilter === null} onClick={() => setWeightFilter(null)}>
              All
            </Chip>
            {weights.map((w) => (
              <Chip
                key={w}
                active={weightFilter === w}
                onClick={() => setWeightFilter(weightFilter === w ? null : w)}
              >
                <span style={{ fontFamily: F.num }}>{num(w)}</span> lb
              </Chip>
            ))}
            {weights.length === 0 ? (
              <span className="text-sm" style={{ color: C.muted, fontFamily: F.ui }}>
                Log a set first.
              </span>
            ) : null}
          </div>

          <div className="mt-4">
            <Eyebrow>Variant</Eyebrow>
          </div>
          <div className="mt-2 flex flex-wrap gap-2">
            <Chip active={variantFilter === null} onClick={() => setVariantFilter(null)}>
              All
            </Chip>
            {exercise.variants.map((v) => (
              <Chip
                key={v.id}
                active={variantFilter === v.id}
                onClick={() => setVariantFilter(variantFilter === v.id ? null : v.id)}
              >
                {v.name}
              </Chip>
            ))}
            {exercise.variants.length === 0 ? (
              <span className="text-sm" style={{ color: C.muted, fontFamily: F.ui }}>
                No variants on this exercise.
              </span>
            ) : null}
          </div>

          {exercise.unilateral ? (
            <>
              <div className="mt-4">
                <Eyebrow>Side</Eyebrow>
              </div>
              <div className="mt-2 flex flex-wrap gap-2">
                <Chip active={sideFilter === null} onClick={() => setSideFilter(null)}>
                  Both
                </Chip>
                {SIDES.map((s) => (
                  <Chip
                    key={s.id}
                    active={sideFilter === s.id}
                    onClick={() => setSideFilter(sideFilter === s.id ? null : s.id)}
                  >
                    {s.name}
                  </Chip>
                ))}
              </div>
            </>
          ) : null}
        </div>
      ) : null}

      {showGraph ? (
        <Graph
          sets={filtered}
          weightFilter={weightFilter}
          variantLabel={
            [variantFilter ? variantName(variantFilter) : null, sideName(sideFilter)]
              .filter(Boolean)
              .join(" · ") || null
          }
        />
      ) : null}

      <div className="mt-5">
        <Eyebrow>
          {filtered.length} {filtered.length === 1 ? "set" : "sets"}
          {activeCount ? " matching" : " logged"}
        </Eyebrow>

        {filtered.length === 0 ? (
          <div
            className="mt-3 rounded-xl p-5 text-sm"
            style={{
              background: C.surface,
              border: `1px dashed ${C.line}`,
              color: C.muted,
              fontFamily: F.ui,
            }}
          >
            {allSets.length === 0
              ? "No sets yet. Tap Log a set to start the history."
              : "No sets match these filters."}
          </div>
        ) : (
          <div className="mt-3 space-y-5">
            {groups.map((g) => (
              <div key={g.key}>
                <div className="flex items-center gap-3">
                  <Eyebrow>{fmtDay(g.at)}</Eyebrow>
                  <div className="flex-1 h-px" style={{ background: C.line }} />
                </div>
                <div className="mt-2 space-y-2">
                  {g.items.map((s) => (
                    <SetRow
                      key={s.id}
                      set={s}
                      isRecord={records.has(s.id)}
                      variant={variantName(s.variantId)}
                      onEdit={() => setEditing(s)}
                    />
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="fixed bottom-0 left-0 right-0 z-30 pointer-events-none">
        <div className="mx-auto max-w-md px-4 pt-6 pointer-events-auto"
          style={{
            paddingBottom: "calc(16px + env(safe-area-inset-bottom, 0px))",
            background: `linear-gradient(to top, ${C.ink} 55%, rgba(14,18,20,0))`,
          }}
        >
          <button
            type="button"
            onClick={() => setLogging(true)}
            className="w-full h-14 rounded-xl text-base"
            style={{ background: C.text, color: C.ink, fontFamily: F.ui, fontWeight: 700 }}
          >
            Log a set
          </button>
        </div>
      </div>

    </div>
  );
}

function SetRow({ set, isRecord, variant, onEdit }) {
  return (
    <button
      type="button"
      onClick={onEdit}
      className="w-full text-left rounded-xl px-4 py-3"
      style={{
        background: isRecord ? "rgba(227,163,59,0.07)" : C.surface,
        border: `1px solid ${C.line}`,
        borderLeftWidth: 3,
        borderLeftColor: isRecord ? C.brass : C.line,
      }}
    >
      <div className="flex items-center justify-between gap-3">
        <div className="flex items-baseline gap-2">
          <span
            style={{
              fontFamily: F.num,
              fontSize: 27,
              fontWeight: 700,
              color: C.text,
              fontVariantNumeric: "tabular-nums",
              letterSpacing: "-0.02em",
            }}
          >
            {num(set.weight)}
          </span>
          <span className="text-xs" style={{ color: C.muted, fontFamily: F.ui }}>
            lb
          </span>
          <span
            style={{
              fontFamily: F.num,
              fontSize: 20,
              fontWeight: 600,
              color: C.text,
              marginLeft: 4,
              fontVariantNumeric: "tabular-nums",
            }}
          >
            × {set.reps}
          </span>
        </div>
        {isRecord ? (
          <span className="flex items-center gap-1" style={{ color: C.brass }}>
            <Trophy size={18} strokeWidth={2.2} />
          </span>
        ) : null}
      </div>

      {variant || set.side || set.rir != null ? (
        <div className="mt-1.5 flex flex-wrap items-center gap-2">
          {set.side ? (
            <span
              className="px-2 py-0.5 rounded text-[12px]"
              style={{
                background: C.raised,
                color: C.text,
                fontFamily: F.ui,
                fontWeight: 700,
              }}
            >
              {sideName(set.side)}
            </span>
          ) : null}
          {variant ? (
            <span
              className="px-2 py-0.5 rounded text-[12px]"
              style={{
                border: `1px solid ${C.line}`,
                color: C.text,
                fontFamily: F.ui,
                fontWeight: 600,
              }}
            >
              {variant}
            </span>
          ) : null}
          {set.rir != null ? (
            <span
              className="text-[12px]"
              style={{ color: C.muted, fontFamily: F.num, fontWeight: 600 }}
            >
              {rirLabel(set.rir, set.rirMaybe)}
            </span>
          ) : null}
        </div>
      ) : null}

      {set.note ? (
        <div
          className="mt-1.5 text-[13px] leading-snug"
          style={{ color: C.muted, fontFamily: F.ui }}
        >
          {set.note}
        </div>
      ) : null}
    </button>
  );
}


/* ------------------------------------------------------------- set sheet */

function SetSheet({
  exercise,
  lastSet,
  editSet,
  presetVariant,
  presetWeight,
  presetSide,
  onAddVariant,
  onClose,
  onSave,
  onDelete,
}) {
  /* Prefill the side: the filter wins, then alternate from a set logged today, then left. */
  const [side, setSide] = useState(() => {
    if (!exercise.unilateral) return null;
    if (editSet) return editSet.side || null;
    if (presetSide) return presetSide;
    if (lastSet && lastSet.side && dayKey(lastSet.at) === dayKey(new Date().toISOString())) {
      return lastSet.side === "L" ? "R" : "L";
    }
    return "L";
  });
  const [field, setField] = useState("reps");
  const [reps, setReps] = useState(editSet ? String(editSet.reps) : "");
  const [weight, setWeight] = useState(() => {
    if (editSet) return num(editSet.weight);
    if (presetWeight !== null && presetWeight !== undefined) return num(presetWeight);
    if (lastSet) return num(lastSet.weight);
    return "";
  });
  const [variantId, setVariantId] = useState(
    editSet ? editSet.variantId : presetVariant || lastSet?.variantId || null
  );
  const [rir, setRir] = useState(editSet && editSet.rir != null ? editSet.rir : null);
  const [rirMaybe, setRirMaybe] = useState(Boolean(editSet && editSet.rirMaybe));
  const [note, setNote] = useState(editSet ? editSet.note || "" : "");
  const [newVariant, setNewVariant] = useState("");
  const [addingVariant, setAddingVariant] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(false);

  const repsNum = parseInt(reps, 10);
  const weightNum = parseFloat(weight);
  const valid = repsNum > 0 && !Number.isNaN(weightNum) && weightNum >= 0;

  const type = (ch) => {
    const set = field === "reps" ? setReps : setWeight;
    const cur = field === "reps" ? reps : weight;
    if (ch === "." && (field === "reps" || cur.includes("."))) return;
    if (cur.length > 6) return;
    set((cur === "0" && ch !== "." ? "" : cur) + ch);
  };

  const back = () => {
    const set = field === "reps" ? setReps : setWeight;
    set((c) => c.slice(0, -1));
  };

  const bump = (delta) => {
    const base = Number.isNaN(weightNum) ? 0 : weightNum;
    setWeight(num(Math.max(0, Math.round((base + delta) * 100) / 100)));
  };

  const commitVariant = () => {
    const name = newVariant.trim();
    if (!name) return;
    const id = onAddVariant(name);
    if (id) setVariantId(id);
    setNewVariant("");
    setAddingVariant(false);
  };

  const save = () => {
    if (!valid) return;
    onSave({
      id: editSet ? editSet.id : uid(),
      exerciseId: exercise.id,
      variantId: variantId || null,
      weight: weightNum,
      reps: repsNum,
      rir,
      rirMaybe: rir != null && rirMaybe,
      side: exercise.unilateral ? side : editSet ? editSet.side || null : null,
      note: note.trim(),
      at: editSet ? editSet.at : new Date().toISOString(),
    });
  };

  const Readout = ({ label, value, unit, target }) => (
    <button
      type="button"
      onClick={() => setField(target)}
      className="flex-1 rounded-xl px-3 py-2 text-left"
      style={{
        background: C.raised,
        border: `2px solid ${field === target ? C.text : "transparent"}`,
      }}
    >
      <Eyebrow>{label}</Eyebrow>
      <div className="flex items-baseline gap-1">
        <span
          style={{
            fontFamily: F.num,
            fontSize: 34,
            fontWeight: 700,
            color: value ? C.text : C.line,
            fontVariantNumeric: "tabular-nums",
            letterSpacing: "-0.02em",
          }}
        >
          {value || "0"}
        </span>
        <span className="text-xs" style={{ color: C.muted, fontFamily: F.ui }}>
          {unit}
        </span>
      </div>
    </button>
  );

  const keys = ["1", "2", "3", "4", "5", "6", "7", "8", "9", ".", "0"];

  return (
    <Sheet
      onClose={onClose}
      title={editSet ? "Edit set" : "Log a set"}
      subtitle={editSet ? `${exercise.name} · ${fmtDay(editSet.at)}` : exercise.name}
    >
      {exercise.note ? (
        <div
          className="mb-4 rounded-xl px-3 py-2.5 text-[14px] leading-snug whitespace-pre-line"
          style={{
            background: C.surface,
            borderLeft: `3px solid ${C.muted}`,
            color: C.text,
            fontFamily: F.ui,
          }}
        >
          {exercise.note}
        </div>
      ) : null}
      <div className="flex gap-2">
        <Readout label="Reps" value={reps} unit="reps" target="reps" />
        <Readout label="Weight" value={weight} unit="lb" target="weight" />
      </div>

      <div className="mt-2 grid grid-cols-4 gap-2">
        {[-10, -2.5, 2.5, 10].map((d) => (
          <button
            key={d}
            type="button"
            onClick={() => bump(d)}
            className="h-11 rounded-lg"
            style={{
              background: C.raised,
              color: C.text,
              border: `1px solid ${C.line}`,
              fontFamily: F.num,
              fontWeight: 700,
              fontSize: 15,
            }}
          >
            {d > 0 ? `+${d}` : d}
          </button>
        ))}
      </div>

      <div className="mt-3 grid grid-cols-3 gap-2">
        {keys.map((k) => (
          <button
            key={k}
            type="button"
            onClick={() => type(k)}
            className="h-14 rounded-xl"
            style={{
              background: C.raised,
              color: C.text,
              fontFamily: F.num,
              fontSize: 22,
              fontWeight: 600,
            }}
          >
            {k}
          </button>
        ))}
        <button
          type="button"
          onClick={back}
          aria-label="Backspace"
          className="h-14 rounded-xl flex items-center justify-center"
          style={{ background: C.raised, color: C.muted }}
        >
          <Backspace size={22} />
        </button>
      </div>

      {exercise.unilateral ? (
        <div className="mt-5">
          <Eyebrow>Side</Eyebrow>
          <div className="mt-2 grid grid-cols-2 gap-2">
            {SIDES.map((s) => (
              <button
                key={s.id}
                type="button"
                onClick={() => setSide(side === s.id ? null : s.id)}
                className="h-12 rounded-xl text-base"
                style={{
                  background: side === s.id ? C.text : "transparent",
                  color: side === s.id ? C.ink : C.text,
                  border: `1px solid ${side === s.id ? C.text : C.line}`,
                  fontFamily: F.ui,
                  fontWeight: 700,
                }}
              >
                {s.name}
              </button>
            ))}
          </div>
        </div>
      ) : null}

      <div className="mt-5">
        <Eyebrow>Reps in reserve, optional</Eyebrow>
        <div className="mt-2 flex gap-2">
          {RIR_SCALE.map((r) => (
            <button
              key={r}
              type="button"
              onClick={() => {
                if (rir === r) {
                  setRir(null);
                  setRirMaybe(false);
                } else {
                  setRir(r);
                }
              }}
              className="h-12 flex-1 min-w-0 rounded-lg"
              style={{
                background: rir === r ? C.text : "transparent",
                color: rir === r ? C.ink : C.text,
                border: `1px solid ${rir === r ? C.text : C.line}`,
                fontFamily: F.num,
                fontWeight: 700,
                fontSize: 15,
              }}
            >
              {r}
            </button>
          ))}
          <button
            type="button"
            disabled={rir == null}
            aria-pressed={rirMaybe}
            aria-label={rir == null ? "Maybe one more" : `Maybe ${rir + 1}`}
            onClick={() => setRirMaybe((m) => !m)}
            className="h-12 shrink-0 rounded-lg px-2 flex flex-col items-center justify-center leading-none"
            style={{
              width: 72,
              background: rirMaybe && rir != null ? C.brass : "transparent",
              color: rir == null ? C.line : rirMaybe ? C.ink : C.brass,
              border: `1px ${rirMaybe && rir != null ? "solid" : "dashed"} ${
                rir == null ? C.line : C.brass
              }`,
              fontFamily: F.ui,
            }}
          >
            <span className="text-[10px] uppercase tracking-[0.12em]" style={{ fontWeight: 700 }}>
              maybe
            </span>
            <span className="mt-1" style={{ fontFamily: F.num, fontWeight: 700, fontSize: 16 }}>
              {rir == null ? "+1" : rir + 1}
            </span>
          </button>
        </div>
        <div className="mt-2 text-[12px]" style={{ color: C.muted, fontFamily: F.ui }}>
          {rir == null
            ? "0 means the set went to failure."
            : rirLabel(rir, rirMaybe)}
        </div>
      </div>

      <div className="mt-5">
        <Eyebrow>Variant, optional</Eyebrow>
        <div className="mt-2 flex flex-wrap gap-2">
          {exercise.variants.map((v) => (
            <Chip
              key={v.id}
              active={variantId === v.id}
              onClick={() => setVariantId(variantId === v.id ? null : v.id)}
            >
              {v.name}
            </Chip>
          ))}
          <button
            type="button"
            onClick={() => setAddingVariant((a) => !a)}
            className="px-3 h-10 rounded-lg text-sm flex items-center gap-1"
            style={{
              fontFamily: F.ui,
              fontWeight: 600,
              color: C.text,
              border: `1px dashed ${C.line}`,
            }}
          >
            <Plus size={16} strokeWidth={2.5} />
            New variant
          </button>
        </div>
        {addingVariant ? (
          <div className="mt-2 flex gap-2">
            <input
              autoFocus
              value={newVariant}
              onChange={(e) => setNewVariant(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && commitVariant()}
              placeholder="Wide grip"
              className="flex-1 h-12 px-3 rounded-xl text-base"
              style={{
                background: C.raised,
                border: `1px solid ${C.line}`,
                color: C.text,
                fontFamily: F.ui,
              }}
            />
            <button
              type="button"
              onClick={commitVariant}
              className="h-12 px-4 rounded-xl"
              style={{
                background: C.text,
                color: C.ink,
                fontFamily: F.ui,
                fontWeight: 700,
              }}
            >
              Add
            </button>
          </div>
        ) : null}
      </div>

      <div className="mt-5">
        <Eyebrow>Note, optional</Eyebrow>
        <input
          value={note}
          onChange={(e) => setNote(e.target.value)}
          placeholder="Felt heavy off the chest"
          className="mt-2 w-full h-12 px-3 rounded-xl text-base"
          style={{
            background: C.raised,
            border: `1px solid ${C.line}`,
            color: C.text,
            fontFamily: F.ui,
          }}
        />
      </div>

      <button
        type="button"
        onClick={save}
        disabled={!valid}
        className="mt-5 w-full h-14 rounded-xl text-base"
        style={{
          background: valid ? C.text : C.raised,
          color: valid ? C.ink : C.muted,
          fontFamily: F.ui,
          fontWeight: 700,
        }}
      >
        {valid
          ? `${editSet ? "Update" : "Save"} ${num(weightNum)} lb × ${repsNum}${
              exercise.unilateral && side ? ` · ${sideName(side)}` : ""
            }`
          : "Enter reps and weight"}
      </button>

      <button
        type="button"
        onClick={onClose}
        className="mt-2 w-full h-12 rounded-xl flex items-center justify-center gap-1 text-base"
        style={{
          background: "transparent",
          border: `1px solid ${C.line}`,
          color: C.text,
          fontFamily: F.ui,
          fontWeight: 600,
        }}
      >
        <ChevronLeft size={18} />
        Back without saving
      </button>

      {editSet ? (
        confirmDelete ? (
          <div className="mt-4 flex items-center gap-2">
            <span className="text-sm flex-1" style={{ color: C.muted, fontFamily: F.ui }}>
              Delete this set for good?
            </span>
            <button
              type="button"
              onClick={() => setConfirmDelete(false)}
              className="h-11 px-3 rounded-lg text-sm"
              style={{
                border: `1px solid ${C.line}`,
                color: C.text,
                fontFamily: F.ui,
                fontWeight: 600,
              }}
            >
              Keep
            </button>
            <button
              type="button"
              onClick={() => onDelete(editSet.id)}
              className="h-11 px-3 rounded-lg text-sm"
              style={{
                background: C.brass,
                color: C.ink,
                fontFamily: F.ui,
                fontWeight: 700,
              }}
            >
              Delete
            </button>
          </div>
        ) : (
          <button
            type="button"
            onClick={() => setConfirmDelete(true)}
            className="mt-4 w-full h-12 rounded-xl flex items-center justify-center gap-2 text-sm"
            style={{ color: C.brass, fontFamily: F.ui, fontWeight: 600 }}
          >
            <Trash2 size={17} />
            Delete set
          </button>
        )
      ) : null}
    </Sheet>
  );
}


/* ----------------------------------------------------------------- graph */

function Graph({ sets, weightFilter, variantLabel }) {
  const fixedWeight = weightFilter !== null && weightFilter !== undefined;

  const points = useMemo(
    () =>
      sets.map((s) => ({
        y: fixedWeight ? s.reps : Math.round(epley(s.weight, s.reps) * 10) / 10,
        label: fixedWeight ? String(s.reps) : num(Math.round(epley(s.weight, s.reps) * 10) / 10),
        sub: `(${num(s.weight)} × ${s.reps})`,
        date: fmtShort(s.at),
      })),
    [sets, fixedWeight]
  );

  const H = 260;
  const TOP = 54;
  const BOTTOM = 34;
  const SPACING = 92;
  const SIDE = 30;
  const width = Math.max(SIDE * 2, SIDE * 2 + (points.length - 1) * SPACING);

  const vals = points.map((p) => p.y);
  let min = vals.length ? Math.min(...vals) : 0;
  let max = vals.length ? Math.max(...vals) : 1;
  if (max === min) {
    const pad = Math.max(1, Math.abs(max) * 0.1);
    min -= pad;
    max += pad;
  } else {
    const pad = (max - min) * 0.15;
    min -= pad;
    max += pad;
  }
  if (min < 0) min = 0;

  const y = (v) => TOP + (1 - (v - min) / (max - min)) * (H - TOP - BOTTOM);
  const x = (i) => SIDE + i * SPACING;
  const ticks = [0, 1, 2, 3].map((i) => min + ((max - min) * i) / 3);

  const path = points.map((p, i) => `${i === 0 ? "M" : "L"} ${x(i)} ${y(p.y)}`).join(" ");

  const title = fixedWeight
    ? `Reps at ${num(weightFilter)} lb`
    : "Estimated 1RM, Epley";
  const best = points.length ? Math.max(...vals) : null;

  return (
    <div
      className="mt-3 rounded-xl overflow-hidden"
      style={{ background: C.surface, border: `1px solid ${C.line}` }}
    >
      <div className="px-4 pt-3 pb-2">
        <Eyebrow>{variantLabel ? `${title} · ${variantLabel}` : title}</Eyebrow>
        {best !== null ? (
          <div className="mt-0.5" style={{ fontFamily: F.ui, color: C.text }}>
            <span style={{ fontFamily: F.num, fontWeight: 700, fontSize: 20 }}>
              {num(best)}
            </span>
            <span className="text-xs ml-1" style={{ color: C.muted }}>
              best {fixedWeight ? "reps" : "lb"}
            </span>
          </div>
        ) : null}
      </div>

      {points.length === 0 ? (
        <div
          className="px-4 pb-5 text-sm"
          style={{ color: C.muted, fontFamily: F.ui }}
        >
          No sets match these filters yet.
        </div>
      ) : (
        <div className="flex">
          <svg width={46} height={H} className="shrink-0">
            {ticks.map((t, i) => (
              <text
                key={i}
                x={42}
                y={y(t) + 4}
                textAnchor="end"
                style={{ fontFamily: F.num, fontSize: 10, fill: C.muted }}
              >
                {num(Math.round(t * 10) / 10)}
              </text>
            ))}
          </svg>

          <div className="overflow-x-auto no-bar flex-1 pb-2">
            <svg width={width} height={H} style={{ display: "block" }}>
              {ticks.map((t, i) => (
                <line
                  key={i}
                  x1={0}
                  x2={width}
                  y1={y(t)}
                  y2={y(t)}
                  stroke={C.line}
                  strokeWidth={1}
                />
              ))}

              {points.length > 1 ? (
                <path d={path} fill="none" stroke={C.brass} strokeWidth={2} />
              ) : null}

              {points.map((p, i) => {
                const py = y(p.y);
                const labelY = Math.max(20, py - 26);
                return (
                  <g key={i}>
                    <circle
                      cx={x(i)}
                      cy={py}
                      r={4.5}
                      fill={C.ink}
                      stroke={C.brass}
                      strokeWidth={2.5}
                    />
                    <text
                      x={x(i)}
                      y={labelY}
                      textAnchor="middle"
                      style={{
                        fontFamily: F.num,
                        fontSize: 13,
                        fontWeight: 700,
                        fill: C.text,
                      }}
                    >
                      {p.label}
                    </text>
                    <text
                      x={x(i)}
                      y={labelY + 13}
                      textAnchor="middle"
                      style={{ fontFamily: F.num, fontSize: 11, fill: C.muted }}
                    >
                      {p.sub}
                    </text>
                    <text
                      x={x(i)}
                      y={H - 12}
                      textAnchor="middle"
                      style={{ fontFamily: F.ui, fontSize: 11, fill: C.muted }}
                    >
                      {p.date}
                    </text>
                  </g>
                );
              })}
            </svg>
          </div>
        </div>
      )}
    </div>
  );
}
